from pathlib import Path
import argparse,json
p=argparse.ArgumentParser();p.add_argument('name');p.add_argument('--mode',type=int,default=1);p.add_argument('--steps',type=int,required=True);p.add_argument('--map',type=int,default=20000);p.add_argument('--anneal',type=int,default=2000000);p.add_argument('--finishes',type=int,default=0);p.add_argument('--groups',type=int,default=5);p.add_argument('--handles',type=int,default=4);p.add_argument('--temperature',type=float,default=.12);p.add_argument('--kick',type=int,default=-1);p.add_argument('--first',type=int,default=0);p.add_argument('--release-mode',type=int,default=0);p.add_argument('--keep-columns',type=int,default=0);p.add_argument('--transfer',type=int,default=0);p.add_argument('--cut',type=int,default=0);p.add_argument('--cutoff',type=int,default=26);p.add_argument('--exact',type=int,default=0);p.add_argument('--missing',type=float,default=10.);p.add_argument('--map-match',type=int,default=0);p.add_argument('--base-map',type=int,default=450000);p.add_argument('--base-anneal',type=int,default=11175000);p.add_argument("--preferred",type=int,default=0);p.add_argument("--preferred-weight",type=float,default=.15);p.add_argument("--soft",type=float,default=0.);p.add_argument("--min-windows",type=int,default=0);a=p.parse_args()
root=Path(__file__).resolve().parents[2];s=(root/'solutions/lns-star/main.cpp').read_text()
for x,y in [('env_int("LNS_PREFERRED_PAIRS")',f'int(env_real("LNS_PREFERRED_PAIRS",{a.preferred}))'),('env_real("LNS_PREFERRED_WEIGHT",.15)',f'env_real("LNS_PREFERRED_WEIGHT",{a.preferred_weight})'),('env_real("LNS_SOFT_PENALTY",0.)',f'env_real("LNS_SOFT_PENALTY",{a.soft})'),('env_int("LNS_MIN_WINDOWS")',f'int(env_real("LNS_MIN_WINDOWS",{a.min_windows}))'),('std::max(0,env_int("LNS_MODE"))',f'int(env_real("LNS_MODE",{a.mode}))'),('std::max(0,env_int("LNS_STEPS"))',f'int(env_real("LNS_STEPS",{a.steps}))'),('env_real("LNS_MAP_ITERS",20000)',f'env_real("LNS_MAP_ITERS",{a.map})'),('env_real("LNS_ANNEAL_ITERS",2000000)',f'env_real("LNS_ANNEAL_ITERS",{a.anneal})'),('env_real("LNS_LOCAL_FINISHES",0)',f'env_real("LNS_LOCAL_FINISHES",{a.finishes})'),('env_real("LNS_GROUPS",5)',f'env_real("LNS_GROUPS",{a.groups})'),('env_real("LNS_HANDLES",4)',f'env_real("LNS_HANDLES",{a.handles})'),('env_real("LNS_MAP_TEMP",.12)',f'env_real("LNS_MAP_TEMP",{a.temperature})'),('env_real("LNS_KICK",-1)',f'env_real("LNS_KICK",{a.kick})'),('env_real("LNS_FIRST_SEG",0)',f'env_real("LNS_FIRST_SEG",{a.first})'),('env_real("LNS_RELEASE_MODE",0)',f'env_real("LNS_RELEASE_MODE",{a.release_mode})'),('env_int("LNS_KEEP_COLUMNS")',f'int(env_real("LNS_KEEP_COLUMNS",{a.keep_columns}))'),('env_int("LNS_TRANSFER_HOLES")',f'int(env_real("LNS_TRANSFER_HOLES",{a.transfer}))'),('env_int("LNS_CUT")',f'int(env_real("LNS_CUT",{a.cut}))'),('env_real("LNS_CUTOFF",26)',f'env_real("LNS_CUTOFF",{a.cutoff})'),('env_int("LNS_MAP_EXACT")',f'int(env_real("LNS_MAP_EXACT",{a.exact}))'),('env_real("LNS_MISSING",10.)',f'env_real("LNS_MISSING",{a.missing})'),('env_int("LNS_USE_MAP_MATCH")',f'int(env_real("LNS_USE_MAP_MATCH",{a.map_match}))')]:
 assert s.count(x)==1,(x,s.count(x));s=s.replace(x,y)
s=s.replace('kMapIters = int(450000 * ITER_SCALE)',f'kMapIters = int({a.base_map} * ITER_SCALE)').replace('kAnnealIters = int(11175000 * ITER_SCALE)',f'kAnnealIters = int({a.base_anneal} * ITER_SCALE)')
s=s.replace('std::string path=std::string(root)+name;', 'std::string path=std::string(root)+"/'+a.name+'"+name;')
assert a.name.startswith('lns-');d=root/'solutions'/a.name;d.mkdir(exist_ok=True);(d/'main.cpp').write_text(s)
(d/'config.json').write_text(json.dumps(vars(a),indent=2)+'\n')
(d/'README.md').write_text('改良元: solutions/lns-star（注文処理は solutions/deval-helper-wide と同一）\n\n研究用の固定予算。LNS_MODE 1=領域の破壊修復、2=追加 anneal branches、3=追加 refinishes、4=全設計の独立再実行、5=完成済み最良設計の再焼きなまし、6=比較紙の集合をまたぐ比較窓の極性を一括反転。詳細は lns-star/README.md。\n\n既定設定:\n\n```json\n'+json.dumps(vars(a),indent=2)+'\n```\n\n時間超過を許す研究版のため、評価は --no-record を付ける。全ケースは標準 pahcer_run.py から実行する。\n')
